#include "crash_report.h"
#include <atomic>
#include <csignal>
#include <cstdlib>
#include <sentry.h>
#include "file_access.h"
#include "utf.h"
//generated by the makefiles from SENTRY_DSN, SENTRY_ENVIRONMENT and GIT_SHA (never committed, not on any command line):
#include "crash_report_build.h"

//sentry-native implementation of crash_report.h: Crashpad backend (crashpad_handler runs as a separate process and writes and
//uploads the minidump), curl transport for the reportInternalError() events. No platform-specific calls here: the same code
//builds for Linux, macOS and Windows; only the path conversion differs (sentry-native takes UTF-8, or UTF-16 on Windows).
using namespace zen;


namespace
{
std::atomic<bool> globalActive = false;


//privacy: events carry no user, host or server name, whatever sentry-native or a future version adds by default
void removePersonalData(sentry_value_t event)
{
    sentry_value_remove_by_key(event, "user");
    sentry_value_remove_by_key(event, "server_name");
    sentry_value_remove_by_key(event, "request");
}


//not called for crashes (see onCrash()): only for reportInternalError() events, so it may allocate
sentry_value_t beforeSend(sentry_value_t event, sentry_hint_t* hint, void* userData)
{
    removePersonalData(event);
    return event;
}


/*  Runs in the crashing process, inside the signal handler: must be async-signal-safe, so it does nothing but keep the event.
    Setting it keeps beforeSend() out of the crash path. With Crashpad the event is empty anyway: what is sent is the minidump
    plus the scope (tags, breadcrumbs).                                          */
sentry_value_t onCrash(const sentry_ucontext_t* uctx, sentry_value_t event, sentry_hint_t* hint, void* userData)
{
    return event;
}


std::string toSentryPath(const Zstring& path) { return utfTo<std::string>(path); }
}


const CrashReportBuildInfo& zen::getCrashReportBuildInfo()
{
    static const CrashReportBuildInfo info
    {
        .dsn         = ZEN_CRASH_REPORT_DSN,
        .environment = ZEN_CRASH_REPORT_ENVIRONMENT,
        .gitSha      = ZEN_CRASH_REPORT_GIT_SHA,
    };
    return info;
}


bool zen::isCrashReportingAvailable() { return true; }


void zen::initCrashReporting(const CrashReportConfig& cfg) //throw SysError
{
    if (!cfg.enabled)
        return;
    if (globalActive)
        throw SysError(L"Crash reporting is already initialized.");
    if (cfg.dsn.empty())
        throw SysError(L"No DSN.");

    try
    {
        if (!itemExists(cfg.handlerPath)) //throw FileError
            throw SysError(L"Crash handler not found: " + utfTo<std::wstring>(cfg.handlerPath));

        createDirectoryIfMissingRecursion(cfg.databasePath); //throw FileError

        /* sentry-native keeps the last consent in "<database>/user-consent" and applies it at sentry_init(), before the
           user's current setting is known: pending crash reports of an earlier run would be uploaded at once, even if the
           user has turned reporting off since. Start from "consent unknown" instead (uploads paused) on every run.   */
        const Zstring consentFilePath = appendPath(cfg.databasePath, Zstr("user-consent"));
        if (itemExists(consentFilePath)) //throw FileError
            removeFilePlain(consentFilePath); //throw FileError
    }
    catch (const FileError& e) { throw SysError(e.toString()); }

    sentry_options_t* opts = sentry_options_new();
    if (!opts)
        throw SysError(L"sentry_options_new failed.");

    sentry_options_set_dsn(opts, cfg.dsn.c_str());
    sentry_options_set_release(opts, cfg.release.c_str());
    sentry_options_set_environment(opts, cfg.environment.c_str());
    sentry_options_set_database_path(opts, toSentryPath(cfg.databasePath).c_str());
    sentry_options_set_handler_path(opts, toSentryPath(cfg.handlerPath).c_str());
    if (!cfg.caCertPath.empty())
        sentry_options_set_ca_certs(opts, toSentryPath(cfg.caCertPath).c_str());

    //privacy defaults: no PII, nothing but crashes and internal errors, no extra attachments
    //(send_default_pii: off by default; its setter exists only in sentry-native's Nintendo Switch build)
    sentry_options_set_send_client_reports(opts, 0); //no statistics about dropped events either
    sentry_options_set_require_user_consent(opts, 1); //no upload before setCrashReportingConsent(true)
    sentry_options_set_auto_session_tracking(opts, 0); //no release health sessions: they are neither crashes nor errors
    sentry_options_set_max_breadcrumbs(opts, 50);
    sentry_options_set_attach_stacktrace(opts, 1); //group internal errors by call site
    sentry_options_set_shutdown_timeout(opts, 2000 /*ms*/);
    sentry_options_set_before_send(opts, beforeSend, nullptr);
    sentry_options_set_on_crash(opts, onCrash, nullptr);
    sentry_options_set_debug(opts, ::getenv("FFS_CRASH_REPORT_DEBUG") ? 1 : 0);

    //sentry_init() takes ownership of opts, even on failure
    if (const int rv = sentry_init(opts);
        rv != 0)
        throw SysError(L"sentry_init failed with code " + numberTo<std::wstring>(rv) + L'.');

    //sentry-native gives events a user object with a random installation ID by default: send none at all
    sentry_set_user(sentry_value_new_null());
    sentry_set_tag("app", cfg.appName.c_str());

    globalActive = true;
}


bool zen::isCrashReportingActive() { return globalActive; }


void zen::setCrashReportingConsent(bool consent)
{
    if (!globalActive)
        return;
    if (consent)
        sentry_user_consent_give();
    else
        sentry_user_consent_revoke();
}


void zen::shutdownCrashReporting()
{
    if (!globalActive.exchange(false))
        return;
    sentry_close(); //waits up to the shutdown timeout for pending events
}


void zen::addCrashBreadcrumb(const std::string& category, const std::wstring& message)
{
    if (!globalActive)
        return;
    sentry_value_t crumb = sentry_value_new_breadcrumb("default", utfTo<std::string>(message).c_str());
    sentry_value_set_by_key(crumb, "category", sentry_value_new_string(category.c_str()));
    sentry_add_breadcrumb(crumb);
}


void zen::reportInternalError(const std::wstring& message)
{
    if (!globalActive)
        return;
    sentry_value_t event = sentry_value_new_message_event(SENTRY_LEVEL_ERROR, "internal", utfTo<std::string>(message).c_str());
    sentry_capture_event(event);
}


void zen::triggerTestCrash(TestCrash kind)
{
    switch (kind)
    {
        case TestCrash::segv:
        {
            int* volatile ptr = nullptr; //volatile: the compiler can't know it's null, so it emits a real write
            *ptr = 42;
            std::raise(SIGSEGV); //unreachable unless address 0 is mapped
            break;
        }
        case TestCrash::abort:
            std::abort();
            break;

        case TestCrash::internalError:
            reportInternalError(L"Test internal error (FFS_TEST_CRASH)");
            break;
    }
}
